-## 🤖 CI/CD Integration
-
-### Separate GitHub Actions Workflow
-
-Create `.github/workflows/regression-tests.yml`:
-
-```yaml
-name: Regression Tests
-
-on:
-  push:
-    branches: [main, develop]
-  pull_request:
-    branches: [main, develop]
-  schedule:
-    # Run daily at 2 AM UTC
-    - cron: '0 2 * * *'
-
-jobs:
-  regression-tests:
-    runs-on: ubuntu-latest
-    steps:
-      - uses: actions/checkout@v4
-
-      - name: Setup Node.js
-        uses: actions/setup-node@v4
-        with:
-          node-version: '20'
-
-      - name: Install pnpm
-        uses: pnpm/action-setup@v2
-        with:
-          version: 8
-
-      - name: Install dependencies
-        run: pnpm install
-
-      - name: Create .env.regression
-        run: |
-          echo "BASE_URL=${{ secrets.REGRESSION_BASE_URL }}" >> .env.regression
-          echo "TEST_USER_EMAIL=${{ secrets.REGRESSION_USER_EMAIL }}" >> .env.regression
-          echo "TEST_USER_PASSWORD=${{ secrets.REGRESSION_USER_PASSWORD }}" >> .env.regression
-          echo "TEST_INVITATION_CODE=${{ secrets.TEST_INVITATION_CODE }}" >> .env.regression
